store("insertSolutionBatch", String.raw`async (start, stop, fragment) => {
  const path = "output/302数学二分节真题集（原生LaTeX横屏版）.tex";
  const source = ".question-bank-work/solutions/" + fragment + ".tex";
  const result = await Promise.allSettled([
    tools.exec_command({cmd:"awk '/^% Q / {key=$0} /^\\\\QuestionPage\\{/ {n++; if (n >= " + start + " && n <= " + stop + ") print key \"\\t\" $0}' '" + path + "'",max_output_tokens:4000}),
    tools.exec_command({cmd:"awk '/^% SOLUTION / {n=$3+0} n >= " + start + " && n <= " + stop + "' '" + source + "'",max_output_tokens:15000})
  ]);
  const outputs = result.map(item => {
    if (item.status !== "fulfilled" || item.value.exit_code !== 0 || item.value.original_token_count != null) {
      throw new Error(JSON.stringify(item).slice(0,450));
    }
    return item.value.output;
  });
  const headers = outputs[0].trim().split("\n");
  const answers = [...outputs[1].matchAll(/^% SOLUTION (\d{3}) (\d{4}) (\d+)\n([\s\S]*?)(?=^% SOLUTION |\s*$\s*(?![\s\S]))/gm)];
  if (headers.length !== stop-start+1 || answers.length !== headers.length) throw new Error(JSON.stringify({start,stop,head:headers.length,answers:answers.length}));
  const hunks = headers.map((header, i) => {
    const meta = header.match(/^% Q (\d{4}) (\d+)\t(\\QuestionPage\{[^{}]+\}\{[^{}]+\}\{([^{}]+)\}\{[^{}]+\}\{[^{}]+\}\{(\d{3}) \/ 408\})$/);
    const [,idx,year,num,body] = answers[i];
    if (!meta || meta[1]!==year || meta[2]!==num || meta[5]!==idx || +idx!==start+i ||
        !body.trim().startsWith("\\textbf{入手角度}") || !body.includes("\\textbf{解析}") ||
        body.trim().length<100 || /\\(begin|end)\{QuestionSolution\}/.test(body)) {
      throw new Error(JSON.stringify({meta,idx,year,num,body:body.slice(0,500)}));
    }
    const newLines = ["","\\begin{QuestionSolution}{"+meta[4]+"}",...body.trimEnd().split("\n"),"\\end{QuestionSolution}"];
    return "@@ "+meta[3]+"\n \\QuestionEnd\n"+newLines.map(line=>"+"+line).join("\n");
  });
  const patch = "*** Begin Patch\n*** Update File: "+path+"\n"+hunks.join("\n")+"\n*** End Patch";
  const resultPatch = await tools.apply_patch(patch);
  text({start,stop,characters:patch.length,resultPatch});
}`);
await eval(load("insertSolutionBatch"))(1,20,"001-113");

